&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;D&#201;PLACEMENTFACILIT&#201;SUPR&#202;ME&quot; href=&quot;#D&#201;PLACEMENTFACILIT&#201;SUPR&#202;ME&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;u&gt;&lt;b&gt;D&#233;placement facilit&#233; supr&#234;me&lt;/b&gt;&lt;/u&gt;  
&lt;b&gt;&#201;l&#233;ment&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;&#201;l&#233;ments.html#BOIS&quot; title=&quot;Les &#233;l&#233;ments du cin&#233;tiste&quot;&gt;Bois&lt;/a&gt; ; &lt;b&gt;Type&lt;/b&gt; utilitaire (Mag) ; &lt;b&gt;Niveau&lt;/b&gt; 5 ; &lt;b&gt;Br&#251;lure&lt;/b&gt; 0  
